UPDATE accounts
SET cash_balance   = cash_balance + #{rewardAmount},
    last_quiz_date = #{today}
WHERE user_id = #{userId}
  AND (last_quiz_date IS NULL OR last_quiz_date < #{today})

UPDATE accounts
SET last_quiz_date = #{today}
WHERE user_id = #{userId}
  AND (last_quiz_date IS NULL OR last_quiz_date < #{today})
